14	// View renders the dashboard as a grid of titled boxes. Il n'y a pas de cadre
15	// extérieur : toutes les autres vues encadrent un objet (une table, un
16	// formulaire), le dashboard est fait de groupes hétérogènes qu'un cadre unique
17	// n'aiderait pas à lire.
18	func (m Model) View() string {
19		t := layoutTier(m.width, m.height)
20		colWidth := t.columnWidth(m.width)
21		columns := m.columnsFor(t)
22	
23		m.chartLines = m.fitCharts(columns, colWidth, t)
24		inner := m.innerHeights(columns, colWidth, t)
25	
26		rendered := make([][]string, len(columns))
27		height := 0
28		for i, col := range columns {
29			rendered[i] = m.renderColumn(col, colWidth, inner, t)
30			if len(rendered[i]) > height {
31				height = len(rendered[i])
32			}
33		}
34	
35		pad := theme.EmptyLineBg(sidePadding)
36		gap := theme.EmptyLineBg(columnGap)
37		blank := theme.EmptyLineBg(colWidth)
38	
39		// Une ligne vide sépare la règle de titre de la première rangée : sans
40		// elle, la bordure haute des boîtes touche celle du titre et les deux se
41		// lisent comme un cadre unique.
42		lines := make([]string, 0, height+1)
43		lines = append(lines, theme.EmptyLineBg(m.width))
44		for i := range height {
45			var line strings.Builder
46			line.WriteString(pad)
47			for c, col := range rendered {
48				if c > 0 {
49					line.WriteString(gap)
50				}
51				if i < len(col) {
52					line.WriteString(col[i])
53				} else {
54					line.WriteString(blank)
55				}
56			}
57			lines = append(lines, theme.PadWithBg(line.String(), m.width))
58		}
59		return strings.Join(lines, "\n")
60	}
