62	// columnsFor distributes the active tab's sections over the palier's columns.
63	// À `wide`, la troisième colonne porte le contenu de l'onglet Resources : le
64	// palier décide où se trouve un fait, jamais s'il existe.
65	func (m Model) columnsFor(t tier) [][]section {
66		overview, resources := overviewSections(), resourceSections()
67	
68		if m.activeTab == tabResources {
69			return distribute(resources, t.columns())
70		}
71		if t.columns() == 3 {
72			// À trois colonnes, la disposition est explicite plutôt que découpée en
73			// parts égales : **les trois boîtes à graphes tiennent la première
74			// rangée**. Elles ont la même hauteur — deux courbes chacune — et une
75			// rangée est cadrée sur sa boîte la plus haute, donc les mélanger avec
76			// les boîtes de texte laisserait du vide dans les deux rangées.
77			code, health, host, dockerBox := overview[0], overview[1], overview[2], overview[3]
78			network, storage := resources[0], resources[1]
79			return [][]section{
80				{host, code},
81				{network, health},
82				{dockerBox, storage},
83			}
84		}
85		return distribute(overview, t.columns())
86	}
87	
88	// distribute lays sections into `cols` columns, filling each column top to
89	// bottom — reading order down a column, which is how a stack of boxes is read.
90	func distribute(sections []section, cols int) [][]section {
91		if cols < 1 {
92			cols = 1
93		}
94		perColumn := (len(sections) + cols - 1) / cols
95	
96		out := make([][]section, 0, cols)
97		for start := 0; start < len(sections); start += perColumn {
98			out = append(out, sections[start:min(start+perColumn, len(sections))])
99		}
100		return out
101	}
102	
103	// fitCharts measures how many lines a chart can take.
104	//
105	// La grille est rendue une première fois **sans aucune courbe** : ce qui reste
106	// entre ce squelette et la hauteur disponible est exactement ce que les courbes
107	// peuvent occuper. Elles vivent toutes dans la même rangée et il y en a deux par
108	// boîte, d'où le partage en deux.
109	//
110	// Mesurer plutôt que déduire est ce qui rend le calcul insensible aux boîtes :
111	// Health a gagné huit lignes en devenant un arbre, et aucune constante n'a eu
112	// à être mise à jour.
113	func (m Model) fitCharts(columns [][]section, width int, t tier) int {
114		if t != tierWide {
115			return 1
116		}
117	
118		bare := m
119		bare.chartLines = 0
120		used := leadingBlank
121		for _, height := range bare.innerHeights(columns, width, t) {
122			used += height + theme.BoxChrome
123		}
124	
125		// Le plancher est **une** ligne, pas trois : une courbe braille a besoin de
126		// trois lignes pour valoir mieux qu'un sparkline, mais forcer trois lignes
127		// quand il n'y en a que deux fait déborder la grille — et ce qui déborde
128		// est perdu, pas repoussé. Une courbe basse vaut mieux qu'une ligne coupée.
129		free := (m.height - used) / chartsPerBox
130		return min(max(free, 1), maxChartHeight)
131	}
132	
133	// chartHeightAt reports the chart height this model's size would produce, which
134	// is what the tests assert on: View() measures it on a copy, so it never
135	// survives on the model itself.
136	func (m Model) chartHeightAt(t tier) int {
137		return m.fitCharts(m.columnsFor(t), t.columnWidth(m.width), t)
138	}
139	
140	// innerHeight is the content height every box on screen fills, borders
141	// excluded: the tallest section of the frame.
142	//
143	// Elle est **dérivée des sections**, pas déclarée par le palier. Une constante
144	// pourrait tronquer une section qui grandit — un graphe ajouté en phase 3, une
145	// ligne ajoutée à Health en phase 4 — et la troncature ne se voit pas : la
146	// boîte reste bien formée, elle perd juste sa dernière ligne. Ce qui reste
147	// figé, et c'est le contrat de la phase 1, c'est qu'une section rende le même
148	// nombre de lignes quel que soit l'état de ses données.
149	// Elle est calculée **par rangée**, pas pour la grille entière : les boîtes de
150	// texte tiennent en six lignes et les boîtes à graphes en vingt, donc une
151	// hauteur unique laisserait treize lignes vides dans Health parce que Host, deux
152	// colonnes plus loin, porte deux courbes. Les rangées restent alignées entre
153	// elles, ce qu'une hauteur par boîte perdrait.
154	func (m Model) innerHeights(columns [][]section, width int, t tier) []int {
155		rows := 0
156		for _, col := range columns {
157			rows = max(rows, len(col))
158		}
159	
160		heights := make([]int, rows)
161		for i := range heights {
162			heights[i] = nominalInnerHeight
163			for _, col := range columns {
164				if i >= len(col) {
165					continue
166				}
167				heights[i] = max(heights[i], len(col[i].render(m, width, t)))
168			}
169		}
170		return heights
171	}
172	
173	// renderColumn stacks a column's boxes. Aucune ligne vide entre elles : leurs
174	// bordures séparent déjà, et à 30 lignes le budget vaut exactement deux boîtes.
175	func (m Model) renderColumn(sections []section, width int, inner []int, t tier) []string {
176		var lines []string
177		for i, s := range sections {
178			height := nominalInnerHeight
179			if i < len(inner) {
180				height = inner[i]
181			}
182			content := padTo(s.render(m, width, t), height, theme.BoxContentWidth(width))
183			lines = append(lines, theme.RenderTitledBox(s.title, content, width)...)
184		}
185		return lines
186	}
187	
188	// padTo fills a section's content out to the frame's box height. Il ne tronque
189	// pas : innerHeight est calculée sur ces mêmes sections, donc une ligne perdue
190	// ici serait un bug de calcul, pas un débordement à absorber.
191	func padTo(content []string, height, innerWidth int) []string {
192		out := make([]string, 0, height)
193		out = append(out, content...)
194		for len(out) < height {
195			out = append(out, theme.EmptyLineBg(innerWidth))
196		}
197		return out
198	}
