200	// filterComponents returns service components filtered by SSL type
201	func (m Model) filterComponents(sslOnly bool) []status.ComponentStatus {
202		var result []status.ComponentStatus
203		for _, c := range m.serviceComponents {
204			isSSL := c.Type == status.TypeSSL
205			if sslOnly == isSSL {
206				result = append(result, c)
207			}
208		}
209		return result
210	}
