212	// countStatuses returns OK, Down, Error counts
213	func countStatuses(components []status.ComponentStatus) (ok, down, errCount int) {
214		for _, c := range components {
215			switch c.Status {
216			case status.StatusOK:
217				ok++
218			case status.StatusDown:
219				down++
220			default:
221				errCount++
222			}
223		}
224		return
225	}
