235	// GetFooterHeight returns the footer height for this view (Rule 124): an empty
236	// line, an info line, and the tab bar when there is more than one tab.
237	func (m Model) GetFooterHeight() int {
238		if m.showsTabBar() {
239			return 3
240		}
241		return 2
242	}
