244	// showsTabBar reports whether a tab bar is worth a line. Un seul onglet n'est
245	// pas un choix : la barre dirait « vous êtes ici », ce que l'écran dit déjà.
246	func (m Model) showsTabBar() bool {
247		return tabCountFor(layoutTier(m.width, m.height)) > 1
248	}
