250	// RenderFooter draws the tab bar and the age of the data (Rule 124).
251	//
252	// L'âge n'est pas de la décoration : avec des libellés qui restent en place et
253	// des valeurs à `-`, une donnée périmée ressemble exactement à une donnée
254	// fraîche. C'est le prix des placeholders, pas un ornement.
255	func (m Model) RenderFooter(width int) string {
256		info := theme.EmptyLineBg(width)
257		if age := theme.TimeAgo(m.lastRefresh); age != "" {
258			info = lipgloss.NewStyle().
259				Foreground(theme.ColorHighlight).
260				Background(theme.ColorBackground).
261				Width(width).
262				Align(lipgloss.Center).
263				Render("Updated " + age)
264		}
265	
266		if !m.showsTabBar() {
267			return theme.EmptyLineBg(width) + "\n" + info
268		}
269	
270		tabs := []theme.TabItem{{Label: "Overview"}, {Label: "Resources"}}
271		tabBar := theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.activeTab)), width)
272		return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
273	}
