3	// This file covers Docker network resources — the `docker network` subcommand
4	// family. Not to be confused with ports.go, which reports the host's own
5	// listening sockets by running `ss` inside a --net=host container.
6	
7	import (
8		"encoding/json"
9		"fmt"
10		"sort"
11		"strings"
12	)
13	
14	// Network represents a Docker network
15	type Network struct {
16		ID      string
17		Name    string
18		Driver  string
19		Scope   string
20		Created string
21	}
22	
23	// ListNetworks returns a list of Docker networks
24	func ListNetworks() ([]Network, error) {
25		if err := requireDocker(); err != nil {
26			return nil, err
27		}
28		output, err := dockerOutput("network", "ls", "--format",
29			"{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}\t{{.CreatedAt}}")
30		if err != nil {
31			return nil, wrapErr("docker network ls", err)
32		}
33	
34		var networks []Network
35		for _, line := range splitLines(output) {
36			parts := strings.SplitN(line, "\t", 5)
37			if len(parts) < 4 {
38				continue
39			}
40			n := Network{ID: parts[0], Name: parts[1], Driver: parts[2], Scope: parts[3]}
41			if len(parts) > 4 {
42				n.Created = parts[4]
43			}
44			networks = append(networks, n)
45		}
46		return networks, nil
47	}
48	
49	// CreateNetwork creates a Docker network with the given name and driver
50	func CreateNetwork(name, driver string) error {
51		if driver == "" {
52			driver = "bridge"
53		}
54		return mutate("docker network create", "network", "create", "--driver", driver, name)
55	}
56	
57	// RemoveNetwork removes a Docker network by ID or name
58	func RemoveNetwork(id string) error {
59		return mutate("docker network rm", "network", "rm", id)
60	}
61	
62	// PruneNetworks removes all unused Docker networks
63	func PruneNetworks() (string, error) {
64		return prune("docker network prune", "network", "prune", "-f")
65	}
66	
67	// NetworkContainer represents a container connected to a Docker network
68	type NetworkContainer struct {
69		Name       string
70		IPv4       string
71		MacAddress string
72	}
73	
74	// networkInspectContainer is used for JSON parsing of docker network inspect output
75	type networkInspectContainer struct {
76		Name        string `json:"Name"`
77		MacAddress  string `json:"MacAddress"`
78		IPv4Address string `json:"IPv4Address"`
79	}
80	
81	// networkInspectResult is the top-level JSON structure from docker network inspect
82	type networkInspectResult struct {
83		Containers map[string]networkInspectContainer `json:"Containers"`
84	}
85	
86	// InspectNetwork returns the containers connected to a Docker network by ID or name.
87	func InspectNetwork(id string) ([]NetworkContainer, error) {
88		if err := requireDocker(); err != nil {
89			return nil, err
90		}
91		output, err := dockerOutput("network", "inspect", id)
92		if err != nil {
93			return nil, wrapErr("docker network inspect", err)
94		}
95		return parseNetworkInspect(output)
96	}
97	
98	// parseNetworkInspect turns `docker network inspect` JSON into the connected
99	// container list, sorted by name so the table does not reshuffle between polls.
100	func parseNetworkInspect(output []byte) ([]NetworkContainer, error) {
101		var results []networkInspectResult
102		if err := json.Unmarshal(output, &results); err != nil {
103			return nil, fmt.Errorf("failed to parse network inspect output: %w", err)
104		}
105		if len(results) == 0 {
106			return nil, nil
107		}
108	
109		var containers []NetworkContainer
110		for _, c := range results[0].Containers {
111			// IPv4Address carries a CIDR suffix ("172.17.0.2/16"); drop the mask.
112			ip := c.IPv4Address
113			if idx := strings.Index(ip, "/"); idx > 0 {
114				ip = ip[:idx]
115			}
116			containers = append(containers, NetworkContainer{
117				Name:       c.Name,
118				IPv4:       ip,
119				MacAddress: c.MacAddress,
120			})
121		}
122		sort.Slice(containers, func(i, j int) bool {
123			return containers[i].Name < containers[j].Name
124		})
125		return containers, nil
126	}
127	
128	// RunDiagnosticContainer runs a command in an ephemeral container attached to a Docker network.
129	// The image must include ping, curl, and nc (netcat). Container is removed after execution (--rm).
130	func RunDiagnosticContainer(networkID, image string, command []string) (string, error) {
131		if err := requireDocker(); err != nil {
132			return "", err
133		}
134		args := append([]string{"run", "--rm", "--network", networkID, image}, command...)
135		output, err := dockerCombined(args...)
136		out := strings.TrimSpace(string(output))
137		if err != nil {
138			return out, wrapErr("diagnostic command", err)
139		}
140		return out, nil
141	}
