9	func TestFetchOCIStatsParsesEachResourceType(t *testing.T) {
10		stubOutput(t, "system",
11			"Images\t12\t1.5GB\n"+
12				"Containers\t3\t250MB\n"+
13				"Local Volumes\t7\t400MB\n"+
14				"Build Cache\t20\t2GB\n")
15	
16		got := FetchOCIStats()
17	
18		if !got.Available {
19			t.Error("Available = false although docker responded")
20		}
21		if got.ImagesCount != 12 || got.ImagesSize != "1.5GB" {
22			t.Errorf("images = %d/%q, want 12/\"1.5GB\"", got.ImagesCount, got.ImagesSize)
23		}
24		if got.ContainersCount != 3 || got.ContainersSize != "250MB" {
25			t.Errorf("containers = %d/%q, want 3/\"250MB\"", got.ContainersCount, got.ContainersSize)
26		}
27		// Docker labels the row "Local Volumes", not "Volumes".
28		if got.VolumesCount != 7 || got.VolumesSize != "400MB" {
29			t.Errorf("volumes = %d/%q, want 7/\"400MB\"", got.VolumesCount, got.VolumesSize)
30		}
31		// Le cache de build entrait dans la somme du récupérable, mais sa taille
32		// propre était jetée — or c'est elle qui répond le plus souvent à « où est
33		// passé le disque ».
34		if got.BuildCacheSize != "2GB" {
35			t.Errorf("BuildCacheSize = %q, want %q", got.BuildCacheSize, "2GB")
36		}
37	}
38	
39	// Le reclaimable est sommé sur les trois familles, et le pourcentage que Docker
40	// accole à chaque taille est relatif à sa propre famille : il ne survivrait pas
41	// à l'addition, donc il est écarté.
42	func TestFetchOCIStatsSumsTheReclaimableSpace(t *testing.T) {
43		stubOutput(t, "system",
44			"Images\t12\t1.5GB\t1.2GB (80%)\n"+
45				"Containers\t3\t250MB\t250MB (100%)\n"+
46				"Local Volumes\t7\t400MB\t0B (0%)\n"+
47				"Build Cache\t20\t2GB\t2GB (100%)\n")
48	
49		// 1.2GB + 250MB + 0 + 2GB, en unités décimales comme docker system df.
50		if got := FetchOCIStats().Reclaimable; got != "3.5GB" {
51			t.Errorf("Reclaimable = %q, want %q", got, "3.5GB")
52		}
53	}
54	
55	// Un daemon qui ne rend pas la colonne — un format plus ancien — ne doit pas
56	// produire un "0B" qui se lirait comme « rien à récupérer ».
57	func TestAMissingReclaimableColumnIsNotZero(t *testing.T) {
