9	// errExit stands in for the failure of a docker invocation.
10	var errExit = errors.New("exit status 1")
11	
12	// stubRunner records the invocations it receives and replays canned output.
13	//
14	// Keyed by the first argument (the docker subcommand) so a test can stub
15	// several calls made by one exported function — ListImages, for instance,
16	// issues "image" and "system" calls.
17	type stubRunner struct {
18		// output maps a subcommand to the bytes it should return.
19		output map[string][]byte
20		// err maps a subcommand to the error it should return.
21		err map[string]error
22		// missing makes LookPath fail, simulating a host without Docker.
23		missing bool
24		// calls records every invocation in order.
25		calls []dockerCmd
26	}
27	
28	func (s *stubRunner) LookPath() error {
29		if s.missing {
30			return errors.New("executable file not found in $PATH")
31		}
32		return nil
33	}
34	
35	func (s *stubRunner) Build(args ...string) *exec.Cmd {
36		s.calls = append(s.calls, dockerCmd{Args: args})
37		return exec.Command("docker", args...)
38	}
39	
40	func (s *stubRunner) Run(dc dockerCmd) ([]byte, error) {
41		s.calls = append(s.calls, dc)
42		key := ""
43		if len(dc.Args) > 0 {
44			key = dc.Args[0]
45		}
46		if err, ok := s.err[key]; ok {
47			return s.output[key], err
48		}
49		return s.output[key], nil
50	}
51	
52	// lastArgs returns the arguments of the most recent invocation.
53	func (s *stubRunner) lastArgs() []string {
54		if len(s.calls) == 0 {
55			return nil
56		}
57		return s.calls[len(s.calls)-1].Args
58	}
