60	// stub installs a stubRunner for the duration of the test. Tests using it must
61	// not call t.Parallel: the runner is package-level state.
62	func stub(t *testing.T, s *stubRunner) *stubRunner {
63		t.Helper()
64		previous := runner
65		runner = s
66		t.Cleanup(func() { runner = previous })
67		return s
68	}
69	
70	// stubOutput is the common case: one subcommand returning one canned payload.
71	func stubOutput(t *testing.T, subcommand, output string) *stubRunner {
72		t.Helper()
73		return stub(t, &stubRunner{output: map[string][]byte{subcommand: []byte(output)}})
74	}
