func ociCount(m Model, pick func(shared.OCIStats) int) string {
	switch {
	case m.loadingOCI:
		return unknownValue
	case m.ociStats == nil || !m.ociStats.Available:
		return unavailableValue
	default:
		return countValue(pick(*m.ociStats))
